const STORAGE_KEY = 'gym-routine-v5';
// Shim de almacenamiento: en Claude.ai esto lo resuelve window.storage (persistencia
// por usuario). Acá, para un deploy normal en Vercel, usamos localStorage del navegador
// (persistencia por dispositivo/navegador, no sincroniza entre dispositivos).
const storage = {
  async get(key) {
    try {
      const value = localStorage.getItem(key);
      return value !== null ? { key, value } : null;
    } catch (e) {
      return null;
    }
  },
  async set(key, value) {
    try {
      localStorage.setItem(key, value);
      return { key, value };
    } catch (e) {
      return null;
    }
  },
};


